mapper.select:
select TDY_ACCUMUL_PAY_FEE from PTL_FEE_POSITION
where PORTFOLIO_ID = #{ptlId}
  and 1 = to_date(#{cdate}, 'yyyy-MM-dd') - CDATE
  and PTL_FEE_TYPE = #{feeType}

SELECT SUM(NVL(TDY_UNPAID_INTINCEXP, 0)) FROM (
	select TDY_UNPAID_INTINCEXP from BOK_POSITION_PRDFEE
	where FEE_TYPE = #{feeType}
	  and 1 = to_date(#{cdate}, 'yyyy-MM-dd') - CDATE
	  and FINPROD_ID = #{finprodId}
	  and P_FINPROD_ID IS NULL
	UNION ALL
	select TDY_UNPAID_INTINCEXP from BOK_POSITION_PRDFEE
	where FEE_TYPE = #{feeType}
	  and 1 = to_date(#{cdate}, 'yyyy-MM-dd') - CDATE
	  and FINPROD_ID = #{finprodId}
	  and P_FINPROD_ID IS not NULL
	)

select FINPROD_ID finprodId,FEE_TYPE feeType,BRANCH branch,'' sFinprodId, CDATE cdate, TDY_POSITION tdyPosition, TDY_FEE_RATE tdyFeeRate, TDY_INTINCEXP_ADD tdyIntincexpAdd from BOK_POSITION_PRDFEE where FEE_TYPE = #{feeType} and CDATE >= to_date(#{startDate}, 'yyyy-MM-dd') and CDATE < to_date(#{enddate}, 'yyyy-MM-dd') and FINPROD_ID = #{finprodId}
and BRANCH = #{branch}
and P_FINPROD_ID IS NULL UNION ALL select FINPROD_ID finprodId,FEE_TYPE feeType,BRANCH branch,'' sFinprodId, CDATE cdate, TDY_POSITION tdyPosition, TDY_FEE_RATE tdyFeeRate, TDY_INTINCEXP_ADD tdyIntincexpAdd from BOK_POSITION_PRDFEE where FEE_TYPE = #{feeType} and CDATE >= to_date(#{startDate}, 'yyyy-MM-dd') and CDATE < to_date(#{enddate}, 'yyyy-MM-dd') and P_FINPROD_ID = #{finprodId}
and BRANCH = #{branch}
UNION ALL select B.FINPROD_ID finprodId ,ptl_FEE_TYPE feeType, 0 branch ,'' sFinprodId , CDATE cdate , NVL(TDY_FEE_CAPITAL,0) tdyPosition , NVL(TDY_FEE_RATE,0) tdyFeeRate, TDY_ACCUMUL_PAY_FEE tdyIntincexpAdd from PTL_FEE_POSITION A inner join FIN_PRODUCT_ADD B ON A.PORTFOLIO_ID = B.PORTFOLIO_ID INNER JOIN FIN_PRODUCT C ON B.FINPROD_ID=C.FINPROD_ID where A.ptl_FEE_TYPE = #{feeType} AND C.PROFIT_TYPE = #{profitType} AND C.P_FINPROD_ID IS NULL and A.CDATE >= to_date(#{startDate}, 'yyyy-MM-dd') and A.CDATE < to_date(#{enddate}, 'yyyy-MM-dd') and B.FINPROD_ID = #{finprodId} UNION ALL SELECT decode(BOK_POSITION_PRDFEE.FINPROD_ID,FIN_PRODUCT.FINPROD_MARKET_ID,FIN_PRODUCT1.FINPROD_MARKET_ID,BOK_POSITION_PRDFEE.FINPROD_ID) finprodId, BOK_POSITION_PRDFEE.Fee_Type feeType, 0 AS branch , decode(BOK_POSITION_PRDFEE.P_FINPROD_ID,NULL,FIN_PRODUCT1.FINPROD_MARKET_ID,BOK_POSITION_PRDFEE.Finprod_Id) sFinprodId, BOK_POSITION_PRDFEE.CDATE cdate, BOK_POSITION_PRDFEE.TDY_POSITION AS tdyPosition, BOK_POSITION_PRDFEE.TDY_FEE_RATE AS tdyFeeRate , nvl(BOK_POSITION_PRDFEE.TDY_INTINCEXP_ADD,0) AS tdyIntincexpAdd FROM BOK_POSITION_PRDFEE LEFT JOIN FIN_PRODUCT ON BOK_POSITION_PRDFEE.FINPROD_ID = FIN_PRODUCT.FINPROD_ID LEFT JOIN FIN_PRODUCT FIN_PRODUCT1 ON BOK_POSITION_PRDFEE.P_FINPROD_ID = FIN_PRODUCT1.FINPROD_ID where BOK_POSITION_PRDFEE.FINPROD_ID = #{finprodId}
AND BOK_POSITION_PRDFEE.FEE_TYPE = #{feeType} AND BOK_POSITION_PRDFEE.P_FINPROD_ID IS NOT NULL and BOK_POSITION_PRDFEE.CDATE >= to_date(#{startDate}, 'yyyy-MM-dd') and BOK_POSITION_PRDFEE.CDATE < to_date(#{enddate}, 'yyyy-MM-dd')

select FPA.FINPROD_ID finprodId, BPP.BRANCH branch, '' sFinprodId, SUM(NVL(BPP.TDY_UNPAID_INTINCEXP, 0)) actPayAmt from BOK_POSITION_PRDFEE BPP, FIN_PRODUCT_ADD FPA, FIN_PRODUCT FP where BPP.FINPROD_ID = FPA.FINPROD_ID and FPA.FINPROD_ID = FP.FINPROD_ID
and FPA.PORTFOLIO_ID = #{ptlId}
and BPP.FEE_TYPE = #{feeType}
and BPP.CDATE = to_date(#{calcEndDate}, 'yyyy-MM-dd')
and 1 = to_date(#{calcEndDate}, 'yyyy-MM-dd') -BPP.CDATE
and BPP.P_FINPROD_ID is NULL group by FPA.FINPROD_ID, BPP.BRANCH union all
select FPA.FINPROD_ID finprodId, BPP.BRANCH branch, BPP.FINPROD_ID sFinprodId, SUM(NVL(BPP.TDY_UNPAID_INTINCEXP, 0)) actPayAmt from BOK_POSITION_PRDFEE BPP, FIN_PRODUCT_ADD FPA, FIN_PRODUCT FP,FIN_PRODUCT F1 where BPP.P_FINPROD_ID = FPA.FINPROD_ID and FPA.FINPROD_ID = FP.FINPROD_ID AND F1.P_FINPROD_ID=FPA.FINPROD_ID
and FPA.PORTFOLIO_ID = #{ptlId}
and BPP.FEE_TYPE = #{feeType}
and BPP.CDATE = to_date(#{calcEndDate}, 'yyyy-MM-dd')
and 1 = to_date(#{calcEndDate}, 'yyyy-MM-dd') -BPP.CDATE
group by FPA.FINPROD_ID, BPP.BRANCH,BPP.FINPROD_ID union all
select FPA.FINPROD_ID finprodId, 0 branch, '' sFinprodId, SUM(NVL(PFP.TDY_ACCUMUL_PAY_FEE, 0)) actPayAmt from PTL_FEE_POSITION PFP, FIN_PRODUCT_ADD FPA, FIN_PRODUCT FP where PFP.PORTFOLIO_ID = FPA.PORTFOLIO_ID and FPA.FINPROD_ID = FP.FINPROD_ID
and FPA.PORTFOLIO_ID = #{ptlId}
and PFP.PTL_FEE_TYPE = #{feeType} and 1 = to_date(#{calcEndDate}, 'yyyy-MM-dd') - PFP.CDATE and FP.p_Finprod_Id is null group by FPA.FINPROD_ID

SELECT TEMP.finprodMarketId finprodMarketId, TEMP.finprodId finprodId, TEMP.sFinprodId sFinprodId, TEMP.feeId feeId, SDL.item_value basicBill, TEMP.feeName feeName, TEMP.feeType feeType, TEMP.calcStartDate calcStartDate, TEMP.calcEndDate calcEndDate, TEMP.ccy ccy, TEMP.actPayAmt actPayAmt, TEMP.payAmt payAmt FROM( SELECT FPA.PORTFOLIO_ID finprodMarketId ,FP.Finprod_Id finprodId ,NULL as sFinprodId ,MF.FEE_ID feeId ,MF.BASIC_BILL basicBill ,MF.Fee_Name feeName ,BPP.FEE_TYPE feeType ,TRD_PRODUCT_DEAL.MDATE as calcStartDate ,to_date(#{calcEndDate}, 'yyyy-MM-dd') calcEndDate ,FCI.ccy ,BPP.TDY_UNPAID_INTINCEXP as actPayAmt ,BPP.TDY_UNPAID_INTINCEXP as payAmt FROM FIN_CASH_INFO FCI INNER JOIN FIN_CASH_PAY_RULE FCPR ON FCI.CASH_ID = FCPR.CASH_ID
AND FCPR.PAY_CYCLE != #{payCycle}
AND FCPR.PAY_CYCLE = #{payCycle}
INNER JOIN MST_FEEINFO MF ON FCI.FEE_ID = MF.FEE_ID AND MF.CHARGE_TYPE IN(#{chargeType}) INNER JOIN BOK_POSITION_PRDFEE BPP ON FCI.FINPROD_ID = BPP.FINPROD_ID AND FCI.BRANCH = BPP.BRANCH and FCI.CASH_TYPE_2 = BPP.FEE_TYPE LEFT JOIN ( SELECT MDATE,FINPROD_ID,BRANCH,FINPROD_TYPE2 FROM TRD_PRODUCT_DEAL S WHERE S.PS = #{ps} AND S.IS_CANCEL = #{isCancel} AND MDATE = (select MAX(d.MDATE) from TRD_PRODUCT_DEAL d where d.PS = #{ps} AND d.MDATE < to_date(#{calcEndDate}, 'yyyy-MM-dd') AND d.IS_CANCEL = #{isCancel} AND S.FINPROD_ID=D.FINPROD_ID AND S.BRANCH=D.BRANCH AND S.FINPROD_TYPE2=D.FINPROD_TYPE2 ))TRD_PRODUCT_DEAL on FCI.FINPROD_ID = TRD_PRODUCT_DEAL.FINPROD_ID AND FCI.BRANCH = TRD_PRODUCT_DEAL.BRANCH AND TRD_PRODUCT_DEAL.FINPROD_TYPE2 = BPP.FEE_TYPE LEFT JOIN FIN_PRODUCT FP ON FCI.FINPROD_ID = FP.FINPROD_ID LEFT JOIN FIN_PRODUCT_ADD FPA ON FP.FINPROD_ID = FPA.FINPROD_ID WHERE FCI.CASH_TYPE_1 = #{cashType1} AND FP.P_FINPROD_ID is null AND FPA.PORTFOLIO_ID = #{ptlId} AND FP.FINPROD_ID = #{finprodId} AND MF.FEE_ID = #{feeId} AND BPP.CDATE = (SELECT max(B.CDATE) FROM BOK_POSITION_PRDFEE B WHERE B.FINPROD_ID = BPP.FINPROD_ID AND B.BRANCH = BPP.BRANCH AND BPP.FEE_TYPE = B.FEE_TYPE AND B.CDATE <to_date(#{calcEndDate}, 'yyyy-MM-dd')) UNION SELECT FPA.PORTFOLIO_ID finprodMarketId ,FIN_PRODUCT1.FINPROD_MARKET_ID finprodId ,FP.FINPROD_ID as sFinprodId ,MF.FEE_ID feeId ,MF.BASIC_BILL basicBill ,MF.Fee_Name feeName ,BPP.FEE_TYPE feeType ,TRD_PRODUCT_DEAL.MDATE as calcStartDate ,to_date(#{calcEndDate}, 'yyyy-MM-dd') calcEndDate ,FCI.ccy ,BPP.TDY_UNPAID_INTINCEXP as actPayAmt ,BPP.TDY_UNPAID_INTINCEXP as payAmt FROM FIN_CASH_INFO FCI INNER JOIN FIN_CASH_PAY_RULE FCPR ON FCI.CASH_ID = FCPR.CASH_ID
AND FCPR.PAY_CYCLE != #{payCycle}
AND FCPR.PAY_CYCLE = #{payCycle}
INNER JOIN MST_FEEINFO MF ON FCI.FEE_ID = MF.FEE_ID AND MF.CHARGE_TYPE IN(#{chargeType}) INNER JOIN BOK_POSITION_PRDFEE BPP ON FCI.FINPROD_ID = BPP.FINPROD_ID AND FCI.BRANCH = BPP.BRANCH and FCI.CASH_TYPE_2 = BPP.FEE_TYPE LEFT JOIN ( SELECT MDATE,FINPROD_ID,BRANCH,FINPROD_TYPE2 FROM TRD_PRODUCT_DEAL S WHERE S.PS = #{ps} AND S.IS_CANCEL = #{isCancel} AND MDATE = (select MAX(d.MDATE) from TRD_PRODUCT_DEAL d where d.PS = #{ps} AND d.MDATE < to_date(#{calcEndDate}, 'yyyy-MM-dd') AND d.IS_CANCEL = #{isCancel} AND S.FINPROD_ID=D.FINPROD_ID AND S.BRANCH=D.BRANCH AND S.FINPROD_TYPE2=D.FINPROD_TYPE2 ))TRD_PRODUCT_DEAL on FCI.FINPROD_ID = TRD_PRODUCT_DEAL.FINPROD_ID AND FCI.BRANCH = TRD_PRODUCT_DEAL.BRANCH AND TRD_PRODUCT_DEAL.FINPROD_TYPE2 = BPP.FEE_TYPE LEFT JOIN FIN_PRODUCT FP ON FCI.FINPROD_ID = FP.FINPROD_ID LEFT JOIN FIN_PRODUCT FIN_PRODUCT1 ON BPP.FINPROD_ID = FIN_PRODUCT1.FINPROD_ID
LEFT JOIN FIN_PRODUCT_ADD FPA ON FIN_PRODUCT1.FINPROD_ID = FPA.FINPROD_ID WHERE FCI.CASH_TYPE_1 = #{cashType1} AND FP.P_FINPROD_ID is not null AND FPA.PORTFOLIO_ID = #{ptlId} AND FP.P_FINPROD_ID = #{finprodId} AND MF.FEE_ID = #{feeId} AND BPP.CDATE = (SELECT max(B.CDATE) FROM BOK_POSITION_PRDFEE B WHERE B.FINPROD_ID = BPP.FINPROD_ID AND B.BRANCH = BPP.BRANCH AND BPP.FEE_TYPE = B.FEE_TYPE
AND B.CDATE <to_date(#{calcEndDate}, 'yyyy-MM-dd'))
union all
select PP.PORTFOLIO_ID finprodMarketId ,FPA.FINPROD_ID finprodId ,'' as sFinprodId ,MF.FEE_ID feeId ,MF.BASIC_BILL basicBill ,MF.Fee_Name feeName ,PFP.PTL_FEE_TYPE feeType ,nvl(TRD_PRODUCT_DEAL.MDATE,PP.vdate) as calcStartDate ,to_date(#{calcEndDate}, 'yyyy-MM-dd') calcEndDate ,FCI.ccy ,PFP.TDY_ACCUMUL_PAY_FEE as actPayAmt ,PFP.TDY_ACCUMUL_PAY_FEE as payAmt from PTL_FEE_POSITION PFP, FIN_PRODUCT_ADD FPA, PTL_PORTFOLIO PP,MST_FEEINFO MF, FIN_CASH_INFO FCI LEFT JOIN ( SELECT MDATE,FINPROD_ID,BRANCH,FINPROD_TYPE2 FROM TRD_PRODUCT_DEAL S WHERE S.PS = #{ps} AND S.IS_CANCEL = #{isCancel} AND MDATE = (select MAX(d.MDATE) from TRD_PRODUCT_DEAL d where d.PS = #{ps} AND d.MDATE < to_date(#{calcEndDate}, 'yyyy-MM-dd') AND d.IS_CANCEL = #{isCancel} AND S.FINPROD_ID=D.FINPROD_ID AND S.BRANCH=D.BRANCH AND S.FINPROD_TYPE2=D.FINPROD_TYPE2 ))TRD_PRODUCT_DEAL on FCI.FINPROD_ID = TRD_PRODUCT_DEAL.FINPROD_ID AND FCI.BRANCH = TRD_PRODUCT_DEAL.BRANCH and FCI.CASH_TYPE_2 = TRD_PRODUCT_DEAL.FINPROD_TYPE2 where PFP.PORTFOLIO_ID = FPA.PORTFOLIO_ID and FPA.PORTFOLIO_ID = PP.PORTFOLIO_ID and FCI.FINPROD_ID = FPA.FINPROD_ID and FCI.CASH_TYPE_1 = #{cashType1} and FCI.CASH_TYPE_2 = #{cashType2_C04} and FCI.FEE_ID = MF.FEE_ID and PFP.PTL_FEE_TYPE = FCI.CASH_TYPE_2 AND MF.CHARGE_TYPE = #{chargeType} and FPA.PORTFOLIO_ID = #{ptlId} and PFP.PTL_FEE_TYPE = #{feeType} and 1 = to_date(#{calcEndDate}, 'yyyy-MM-dd') - PFP.CDATE and PP.PROFIT_TYPE = #{profitType} )TEMP left join sys_datadict_list SDL on TEMP.basicBill = SDL.item_code and SDL.dict_code = 'BILL_BASE_FEE_KIND'

    	select t.* from (select row_number() over() as rownum,FP.CCY as ccy ,
			   FP.FINPROD_ID as finprodId,
    		   FP.PROFIT_TYPE as profitType,
			   FPA.DEAL_MODE  as dealMode,
    		   FP.MDATE as mdate
    	  from FIN_PRODUCT FP, FIN_PRODUCT_ADD FPA
			/*,  PA_FIN_PRODUCT*/
    	 where FP.FINPROD_ID = FPA.FINPROD_ID
    	   /*AND FP.FINPROD_ID = PA_FIN_PRODUCT.FINPROD_ID*/

		  	and FPA.PORTFOLIO_ID = #{ptlId}

		  ) t where t.rownum = 1

   		SELECT NVL(TDY_ACCUMUL_PAY_FEE,0)
   		FROM PTL_FEE_POSITION
   		WHERE PTL_FEE_TYPE = #{feeType1}
			AND 1 = to_date(#{cdate}, 'yyyy-MM-dd')-CDATE
			AND PORTFOLIO_ID = #{ptlId}

				AND PTL_FEE_PLACE = #{org}
